useEffect(()=>{if(page!=='welcome'){setSplashExiting(false);return}let redirectTimer:number|undefined;const finish=()=>{setPage('nearby');router.replace('/demo/guest/nearby')};const holdTimer=window.setTimeout(()=>{if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){finish();return}setSplashExiting(true);redirectTimer=window.setTimeout(finish,260)},2000);return()=>{window.clearTimeout(holdTimer);if(redirectTimer)window.clearTimeout(redirectTimer)}},[page,router]);
