function updateDishFavorites(nextUserId:string,id:string){let current:string[]=[];try{current=JSON.parse(localStorage.getItem(dishFavoritesKey(nextUserId))??'[]')}catch{}const next=current.includes(id)?current.filter(x=>x!==id):[...current,id];localStorage.setItem(dishFavoritesKey(nextUserId),JSON.stringify(next));setDishFavorites(next)}
