const menuProductQuantity=(p:Product)=>productRequiresRequiredModifier(p)?0:baseProductQuantity(cart,p.id);
const pickProduct=(p:Product,cartAware=false,contextQuantity?:number)=>{if(cartAware&&a.busy)return;const productLines=cart.map((item,index)=>({item,index})).filter(({item})=>item.productId===p.id);const existing=cartAware&&productLines.length===1?productLines[0]:undefined;setProduct(p);setMods(existing?[...existing.item.modifierIds]:[]);setComment(existing?.item.comment??'');setQuantity(contextQuantity??existing?.item.quantity??1);setProductCartKey(existing?cartConfigurationKey(existing.item):null)};
