{tab==='Сотрудники'&&s.employees.map(e=><Card key={e.id}><h3>{e.name}</h3><p>{e.role} · {e.shift} · Столы: {e.tables.join(', ')||'Весь зал'}</p></Card>)}
{tab==='Гости'&&!s.guests.length&&<Empty>Гости появятся после сканирования QR стола.</Empty>}{tab==='Гости'&&s.guests.map(g=><Card key={g.id}><strong>{g.name}</strong><p>{g.userId?'Зарегистрирован':'Анонимный гость'} · {g.sessionId}</p></Card>)}
{tab==='Лояльность'&&<Card><form onSubmit={e=>{e.preventDefault();const data=new FormData(e.currentTarget);void a.run({type:'setLoyalty',cashbackRate:Number(data.get('cashback'))/100,bonusLimit:Number(data.get('limit'))/100})}}><Input label="Кешбэк, % (от 5)" name="cashback" type="number" min="5" max="100" defaultValue={s.venue.cashbackRate*100}/><label className="field">Максимум оплаты бонусами<select name="limit" defaultValue={s.venue.bonusLimit*100}>{[20,30,40,50].map(n=><option key={n} value={n}>{n}%</option>)}</select></label><Button type="submit">Сохранить</Button></form></Card>}
