{tab==='Отзывы'&&<>{!s.reviews.length&&<Empty>Пока нет отзывов.</Empty>}{s.reviews.map(r=><Card key={r.id}><strong>{r.rating} / 5</strong><p>{r.text}</p></Card>)}</>}
{tab==='Платежи'&&<>{!s.payments.length&&<Empty>Платежи появятся после выбора части счёта.</Empty>}{s.payments.map(p=><Card key={p.id}><h3>{money(p.total)}</h3><Status status={p.status}/><p>{p.method} · {p.id}</p>{s.financialSplits.filter(f=>f.paymentId===p.id).map(f=><div key={f.paymentId}><p>Ресторан: {money(f.venueShare)} · Официант: {money(f.waiterTipShare)}</p><p>MIRA LINK: {money(f.miraCommissionShare)} · Обязательство ресторана: {money(f.venueCommissionLiability)}</p></div>)}</Card>)}</>}
{tab==='Чаевые'&&<><p>Основные {money(Q.getInitialTipsTotal(s))} · Дополнительные {money(Q.getAdditionalTipsTotal(s))}</p>{s.additionalTips.map(t=><Card key={t.id}><p>Чаевые {money(t.tip)} · Официанту {money(t.waiterShare)} · Комиссия {money(t.commission)}</p></Card>)}</>}
{tab==='Коммуникации'&&<>{s.users.map(u=><Card key={u.id}><Toggle label={`${u.name}: маркетинговые Push`} checked={u.marketing} onChange={enabled=>void a.run({type:'setMarketing',userId:u.id,enabled})}/><p>Сервисные уведомления остаются включёнными. В демо отправка только внутри приложения.</p></Card>)}{s.notifications.map(n=><p className="notification" key={n.id}>{n.type} · {n.message}</p>)}</>}
